// Repro 1: git-refs store, same checkpoint, concurrent summary + attribution
// backfill. Both report success; one mutation should survive.
func TestRepro_RefsStore_ConcurrentBackfills(t *testing.T) {
	store := newRefsStore(t)
	ctx := context.Background()
	cid := id.MustCheckpointID("a1b2c3d4e5f6")
	refsWrite(t, store, cid, "sess-1", "transcript line\n")

	var wg sync.WaitGroup
	wg.Add(2)
	start := make(chan struct{})
	var errSummary, errAttr error
	go func() {
		defer wg.Done()
		<-start
		errSummary = store.Write(ctx, SessionSummary{CheckpointID: cid, Summary: &Summary{
			Summary: "the summary text",
		}})
	}()
	go func() {
		defer wg.Done()
		<-start
		errAttr = store.Write(ctx, CheckpointAttribution{CheckpointID: cid, Attribution: &Attribution{
			TotalLines: 42,
		}})
	}()
	close(start)
	wg.Wait()

	t.Logf("summary write err=%v attribution write err=%v", errSummary, errAttr)

	sum, err := store.Read(ctx, cid)
	require.NoError(t, err)
	require.NotNil(t, sum)
	haveSummary := sum.Sessions[0].Summary != nil && sum.Sessions[0].Summary.Summary != ""
	haveAttr := sum.Attribution != nil
	t.Logf("after concurrent backfills: summary_present=%v attribution_present=%v", haveSummary, haveAttr)
	if !haveSummary || !haveAttr {
		t.Errorf("LOST UPDATE: summary_present=%v attribution_present=%v (both writes returned success)", haveSummary, haveAttr)
	}
}

// Repro 2: git-branch (default) store, two DIFFERENT checkpoints written
// concurrently onto the shared v1 branch.
func TestRepro_GitBranchStore_ConcurrentDistinctCheckpoints(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "README.md", "# test")
	testutil.GitAdd(t, dir, "README.md")
	testutil.GitCommit(t, dir, "init")
	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)
	store := NewGitStore(repo, DefaultV1Refs())
	ctx := context.Background()

	cidA := id.MustCheckpointID("aaaaaaaaaaaa")
	cidB := id.MustCheckpointID("bbbbbbbbbbbb")

	mk := func(cid id.CheckpointID, sess string) Session {
		return Session{
			CheckpointID: cid,
			SessionID:    sess,
			Strategy:     "manual-commit",
			Transcript:   redact.AlreadyRedacted([]byte("transcript\n")),
			Prompts:      []string{"do the thing"},
			FilesTouched: []string{"a.go"},
			AuthorName:   "Test Author",
			AuthorEmail:  "test@example.com",
		}
	}

	var wg sync.WaitGroup
	wg.Add(2)
	start := make(chan struct{})
	var errA, errB error
	go func() { defer wg.Done(); <-start; errA = store.Write(ctx, mk(cidA, "sess-a")) }()
	go func() { defer wg.Done(); <-start; errB = store.Write(ctx, mk(cidB, "sess-b")) }()
	close(start)
	wg.Wait()
	t.Logf("write A err=%v  write B err=%v", errA, errB)

	list, err := store.List(ctx)
	require.NoError(t, err)
	seen := map[string]bool{}
	for _, c := range list {
		seen[c.CheckpointID.String()] = true
	}
	t.Logf("after concurrent writes, v1 branch holds %d checkpoints: %v", len(list), seen)
	if !seen[cidA.String()] || !seen[cidB.String()] {
		t.Errorf("LOST UPDATE: A_present=%v B_present=%v (both writes returned success)", seen[cidA.String()], seen[cidB.String()])
	}
}

