// stopHookCmd builds a Stop-hook subprocess for the given session without
// running it, so callers can start several concurrently.
func stopHookCmd(env *TestEnv, sessionID, transcriptPath string) *exec.Cmd {
	input, err := json.Marshal(map[string]string{
		"session_id":      sessionID,
		"transcript_path": transcriptPath,
	})
	if err != nil {
		env.T.Fatalf("marshal stop input: %v", err)
	}
	cmd := exec.CommandContext(context.Background(), getTestBinary(), "hooks", agentClaudeCode, "stop")
	cmd.Dir = env.RepoDir
	cmd.Stdin = bytes.NewReader(input)
	cmd.Env = append(testutil.GitIsolatedEnv(),
		"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+env.ClaudeProjectDir,
	)
	cmd.Env = append(cmd.Env, env.ExtraEnv...)
	cmd.Env = append(cmd.Env, env.checkpointStoreEnv()...)
	return cmd
}

// readCheckpointSummary reads the root metadata.json for a checkpoint off the
// committed metadata branch.
func readCheckpointSummary(env *TestEnv, checkpointID string) (checkpoint.CheckpointSummary, bool) {
	env.T.Helper()
	content, ok := env.ReadFileFromBranch(paths.MetadataBranchName, CheckpointSummaryPath(checkpointID))
	if !ok {
		return checkpoint.CheckpointSummary{}, false
	}
	var summary checkpoint.CheckpointSummary
	if err := json.Unmarshal([]byte(content), &summary); err != nil {
		env.T.Fatalf("parse CheckpointSummary: %v\ncontent: %s", err, content)
	}
	return summary, true
}

// TestConcurrent_TwoStopHooks_SameCheckpoint drives two agents' Stop hooks
// concurrently after a single commit condensed both of their sessions into one
// checkpoint. Both Stop hooks finalize the SAME checkpoint's transcript, each
// under its own per-session flock, so nothing serializes them against each
// other.
func TestConcurrent_TwoStopHooks_SameCheckpoint(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	sessA := env.NewSession()
	sessB := env.NewSession()

	if err := env.SimulateUserPromptSubmitWithTranscriptPath(sessA.ID, sessA.TranscriptPath); err != nil {
		t.Fatalf("prompt A: %v", err)
	}
	if err := env.SimulateUserPromptSubmitWithTranscriptPath(sessB.ID, sessB.TranscriptPath); err != nil {
		t.Fatalf("prompt B: %v", err)
	}

	// Each agent writes a file. Pad the content so transcript redaction and
	// blob writing during finalize take long enough to overlap.
	padding := strings.Repeat("// filler line to widen the write window\n", 400)
	contentA := "package a\n" + padding
	contentB := "package b\n" + padding
	env.WriteFile("agent_a.go", contentA)
	env.WriteFile("agent_b.go", contentB)

	sessA.CreateTranscript("write file a", []FileChange{{Path: "agent_a.go", Content: contentA}})
	sessB.CreateTranscript("write file b", []FileChange{{Path: "agent_b.go", Content: contentB}})

	// One commit, condensing both sessions into a single checkpoint.
	env.GitCommitWithShadowHooksAsAgent("add agent files", "agent_a.go", "agent_b.go")

	checkpointID := env.GetCheckpointIDFromCommitMessage(env.GetHeadHash())
	if checkpointID == "" {
		t.Fatal("commit has no Entire-Checkpoint trailer; scenario setup failed")
	}
	t.Logf("checkpoint: %s", checkpointID)

	before, ok := readCheckpointSummary(env, checkpointID)
	if !ok {
		t.Fatal("checkpoint not on metadata branch after post-commit")
	}
	t.Logf("after post-commit: sessions=%d combined_attribution=%v",
		len(before.Sessions), before.CombinedAttribution != nil)
	if len(before.Sessions) < 2 {
		t.Fatalf("expected a 2-session checkpoint, got %d — scenario setup failed", len(before.Sessions))
	}

	// Both turns end at the same instant.
	cmdA := stopHookCmd(env, sessA.ID, sessA.TranscriptPath)
	cmdB := stopHookCmd(env, sessB.ID, sessB.TranscriptPath)

	var wg sync.WaitGroup
	start := make(chan struct{})
	wg.Add(2)
	var outA, outB []byte
	var errA, errB error
	go func() { defer wg.Done(); <-start; outA, errA = cmdA.CombinedOutput() }()
	go func() { defer wg.Done(); <-start; outB, errB = cmdB.CombinedOutput() }()
	close(start)
	wg.Wait()

	t.Logf("stop A err=%v out=%s", errA, strings.TrimSpace(string(outA)))
	t.Logf("stop B err=%v out=%s", errB, strings.TrimSpace(string(outB)))

	after, ok := readCheckpointSummary(env, checkpointID)
	if !ok {
		t.Fatal("checkpoint vanished from metadata branch after concurrent Stop hooks")
	}
	t.Logf("after concurrent stops: sessions=%d combined_attribution=%v",
		len(after.Sessions), after.CombinedAttribution != nil)

	if len(after.Sessions) != len(before.Sessions) {
		t.Errorf("LOST UPDATE: session count %d -> %d across concurrent Stop hooks",
			len(before.Sessions), len(after.Sessions))
	}
	if before.CombinedAttribution != nil && after.CombinedAttribution == nil {
		t.Error("LOST UPDATE: combined attribution was dropped by a concurrent Stop hook")
	}

	// Each session's transcript must still be reachable at its own path.
	for i, s := range after.Sessions {
		if s.Transcript == "" {
			t.Errorf("session %d has no transcript pointer", i)
			continue
		}
		if _, found := env.ReadFileFromBranch(paths.MetadataBranchName, s.Transcript); !found {
			t.Errorf("LOST UPDATE: session %d transcript %q missing from metadata branch", i, s.Transcript)
		}
	}
}

